  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // painting goes here
  // sky
  brush.fill("#e0f2f1", 255); // Sky blue
  brush.beginShape();
  brush.vertex(0, 0); // Top left of the sky
  brush.vertex(400, 0); // Bottom right of the sky
  brush.vertex(400, 400); // Bottom right of the sky
  brush.vertex(0, 400); // Top left of the sky
  brush.endShape(true);
  // hills
  brush.fill("#7c8b94", 100); // Light green hills
  brush.beginShape();
  brush.vertex(0, 200); // Top left of the hills
  brush.vertex(400, 200); // Bottom right of the hills
  brush.vertex(400, 300); // Bottom right of the hills
  brush.vertex(0, 300); // Top left of the hills
  brush.endShape(true);
  // sun
  brush.fill("#f7464a", 255); // Red sun
  brush.beginShape();
  brush.vertex(200, 100); // Top of the sun
  brush.vertex(200, 170); // Right side of the sun
  brush.vertex(100, 170); // Bottom of the sun
  brush.vertex(100, 100); // Left side of the sun
  brush.endShape(true);
  // hills
  brush.fill("#a5c887", 100); // Medium green hills
  brush.beginShape();
  brush.vertex(0, 450); // Top left of the hills
  brush.vertex(400, 450); // Bottom right of the hills
  brush.vertex(400, 550); // Bottom right of the hills
  brush.vertex(0, 550); // Top left of the hills
  brush.endShape(true);
}

